package vn.hust.restaurant.repository;
import java.sql.*;import java.util.*;import vn.hust.restaurant.config.Database;import vn.hust.restaurant.model.OrderItemView;
public class KitchenRepository {
 public List<OrderItemView> queue() throws SQLException {List<OrderItemView> o=new ArrayList<>();String s="""
 SELECT ct.MaCTGoiMon,ct.MaPhieu,ct.MaMon,CONCAT(b.MaBanCode,' - ',m.TenMon),ct.SoLuong,ct.DonGiaTaiThoiDiem,ct.GhiChuRieng,ct.TrangThaiCheBien,ct.DaTruKho
 FROM ChiTietGoiMon ct JOIN PhieuGoiMon p ON p.MaPhieu=ct.MaPhieu JOIN BanAn b ON b.MaBan=p.MaBan JOIN MonAn m ON m.MaMon=ct.MaMon
 WHERE p.TrangThaiPhieu IN('DA_GUI_BEP','DANG_PHUC_VU','CHO_THANH_TOAN') AND ct.TrangThaiCheBien IN('CHO_LAM','DANG_LAM','DA_XONG')
 ORDER BY CASE ct.TrangThaiCheBien WHEN 'CHO_LAM' THEN 1 WHEN 'DANG_LAM' THEN 2 ELSE 3 END,p.ThoiGianTao,ct.MaCTGoiMon
 """;try(Connection c=Database.getConnection();Statement st=c.createStatement();ResultSet r=st.executeQuery(s)){while(r.next())o.add(new OrderItemView(r.getLong(1),r.getLong(2),r.getInt(3),r.getString(4),r.getInt(5),r.getBigDecimal(6),r.getString(7),r.getString(8),r.getBoolean(9)));}return o;}
 public void updateStatus(long itemId,String status,int employeeId)throws SQLException{Database.inTransaction(c->{int menuId,qty;boolean deducted;String old;try(PreparedStatement p=c.prepareStatement("SELECT MaMon,SoLuong,DaTruKho,TrangThaiCheBien FROM ChiTietGoiMon WITH(UPDLOCK,HOLDLOCK) WHERE MaCTGoiMon=?")){p.setLong(1,itemId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Không tìm thấy món");menuId=r.getInt(1);qty=r.getInt(2);deducted=r.getBoolean(3);old=r.getString(4);}}if("DA_HUY".equals(old))throw new SQLException("Món đã hủy");try(PreparedStatement p=c.prepareStatement("UPDATE ChiTietGoiMon SET TrangThaiCheBien=?,ThoiGianBatDau=CASE WHEN ?='DANG_LAM' AND ThoiGianBatDau IS NULL THEN SYSDATETIME() ELSE ThoiGianBatDau END,ThoiGianHoanThanh=CASE WHEN ?='DA_XONG' THEN SYSDATETIME() ELSE ThoiGianHoanThanh END WHERE MaCTGoiMon=?")){p.setString(1,status);p.setString(2,status);p.setString(3,status);p.setLong(4,itemId);p.executeUpdate();}if("DA_XONG".equals(status)&&!deducted){String q="SELECT MaNL,DinhLuong FROM CongThucMonAn WHERE MaMon=?";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,menuId);try(ResultSet r=p.executeQuery()){while(r.next()){try(PreparedStatement u=c.prepareStatement("UPDATE NguyenLieu SET SoLuongTon=SoLuongTon-? WHERE MaNL=? AND SoLuongTon>=?")){java.math.BigDecimal amount=r.getBigDecimal(2).multiply(java.math.BigDecimal.valueOf(qty));u.setBigDecimal(1,amount);u.setInt(2,r.getInt(1));u.setBigDecimal(3,amount);if(u.executeUpdate()==0)throw new SQLException("Không đủ nguyên liệu cho món; vui lòng cập nhật kho");}}}}try(PreparedStatement p=c.prepareStatement("UPDATE ChiTietGoiMon SET DaTruKho=1 WHERE MaCTGoiMon=?")){p.setLong(1,itemId);p.executeUpdate();}}try(PreparedStatement p=c.prepareStatement("UPDATE PhieuGoiMon SET TrangThaiPhieu='DANG_PHUC_VU' WHERE MaPhieu=(SELECT MaPhieu FROM ChiTietGoiMon WHERE MaCTGoiMon=?) AND TrangThaiPhieu='DA_GUI_BEP'")){p.setLong(1,itemId);p.executeUpdate();}return null;});}
}
